    MC("«Gênant» descreve…", ["*uma situação","uma pessoa tímida|Isso é «verlegen».","uma cor|Não."], "Situação embaraçosa = gênant; pessoa tímida = verlegen.", ["v-genant","v-verlegen"]),
    FE(["Ik","schaam","mijzelf","dood."], 2, "me", "zich dood schamen: Ik schaam me dood.", ["v-zich-dood-schamen"]),
    LI("Iedereen keek naar mij en ik begon te blozen.", ["Iedereen keek naar mij en ik begon te blozen","Iedereen keek naar me en ik begon te blozen"], "Toda a gente olhou para mim e eu comecei a corar.", "beginnen te + infinitivo.", ["v-blozen"]),
    SW("Conte uma situação embaraçosa (3–4 frases, no passado).", ["Vorig jaar heb ik in een restaurant per ongeluk «Ik ben heet» gezegd in plaats van «Ik heb het warm». De ober keek me raar aan en mijn vrienden lachten. Ik schaamde me dood! Nu weet ik het verschil."], ["Situação", "Reação", "Passado correto"], 30, "Momento embaraçoso.", ["v-genant","v-zich-dood-schamen"]),
